select discount_bucket, pending_discount, first_order_date from (select case when discount >= 0.36 then 'high' when discount >= 0.19 then 'mid' else 'low' end as discount_bucket, sum(case when status = 'PENDING' then discount else 0 end) as pending_discount, min(order_date) as first_order_date from orders group by case when discount >= 0.36 then 'high' when discount >= 0.19 then 'mid' else 'low' end) as s where pending_discount < 80 order by discount_bucket desc
